    }

    private int FindMaximum(TrieNode root, int value)
    {
        if (root.Child[0] == null && root.Child[1] == null)
        {
            return -1;
        }

        TrieNode node = root;
        int result = 0;

        for (int bit = 30; bit >= 0; bit--)
        {
            int current = (value >> bit) & 1;
            int wanted = current ^ 1;

            if (node.Child[wanted] != null)
            {
                result |= 1 << bit;
                node = node.Child[wanted];
            }
            else
            {
                node = node.Child[current];
            }
        }

        return result;
    }

    public List<int> MaximizeXor(List<int> nums, List<List<int>> queries)
    {
        List<int> answer = new List<int>();

        foreach (List<int> query in queries)
        {
            int x = query[0];
            int limit = query[1];
            TrieNode root = new TrieNode();

            foreach (int value in nums)
            {
                if (value <= limit)
