```java
class TrieBinary {
    private class BinaryNode{
        private BinaryNode[] children;

        BinaryNode(){
            children = new BinaryNode[2];
        }

        boolean containsKey(int bit) {
            return children[bit] != null;
        }

        BinaryNode get(int bit) {
            return children[bit];
        }

        BinaryNode putIfAbsent(int bit) {
            if(children[bit] == null){
                children[bit] = new BinaryNode();
            }
            return children[bit];
        }
    }

    private final BinaryNode root;
    public TrieBinary() {
        root = new BinaryNode();
    }

    public void insert(int num) {
        BinaryNode node = root;
        for (int i = 31; i>= 0; i--) {
            int bit = (num>>i) & 1;
            node = node.putIfAbsent(bit);
        }
    }

    public int getMaxXor(int num) {
        BinaryNode node = root;
        int maxXor=0;
        for (int i = 31; i>= 0; i--) {
            int bit = (num >> i) & 1;
            if (node.containsKey(1-bit)) {
                maxXor = maxXor | (1 << i);
                node = node.get(1 - bit);
            } else {
                node = node.get(bit);
            }
        }
        return maxXor;
    }
}

class Solution {
    public List<Integer> maximizeXor(int[] nums, int[][] queries) {
        ArrayList<int[]> offlineQueries = new ArrayList<>();
        for(int i=0; i<queries.length; i++) {
            offlineQueries.add(new int[]{queries[i][0], queries[i][1], i});
        }
        offlineQueries.sort(Comparator.comparingInt(a -> a[1]));
        TrieBinary trie = new TrieBinary();
        Arrays.sort(nums);
        int index=0;
        int[] res = new int[queries.length];
        for(int[] q: offlineQueries) {
            int x = q[0];
            int m = q[1];
            int qIndex = q[2];
            while(index < nums.length && nums[index] <= m){
                trie.insert(nums[index]);
                index++;
            }
            res[qIndex] = index == 0 ? -1 : trie.getMaxXor(x);
        }
        List<Integer> ans = new ArrayList<>();
        for(int i: res) ans.add(i);
        return ans;
    }
}
